//! Design tokens (generated by `build.rs` from `design/tokens.json`) plus the few
//! street colours mixed from them.

use bevy::color::{Color, Mix, Srgba};

include!(concat!(env!("OUT_DIR"), "/tokens.rs"));

/// A token as a Bevy colour (sRGB).
pub fn color(rgb: [u8; 3]) -> Color {
    Color::srgb_u8(rgb[0], rgb[1], rgb[2])
}

/// `a` mixed toward `b` by `t` (in sRGB, like CSS `color-mix(in srgb, ...)`).
pub fn mix(a: [u8; 3], b: [u8; 3], t: f32) -> Color {
    let a = Srgba::rgb_u8(a[0], a[1], a[2]);
    let b = Srgba::rgb_u8(b[0], b[1], b[2]);
    a.mix(&b, t).into()
}

/// Canal water: paper washed with the focus blue.
pub fn water() -> Color {
    mix(PAPER_DEEP, FOCUS, 0.28)
}

/// A traffic light that is green: the `ok` token, lifted so it reads as lit.
pub fn signal_green() -> Color {
    mix(OK, HIGHLIGHT, 0.35)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tokens_come_from_design_tokens_json() {
        assert_eq!(PAPER, [0xf6, 0xf0, 0xe4]);
        assert_eq!(INK, [0x2a, 0x26, 0x20]);
        assert_eq!(ACCENT, [0xe2, 0x57, 0x2b]);
        assert_eq!(CARD, [0xff, 0xfd, 0xf7]);
        assert!((BOIL_STEP - 0.18).abs() < 1e-6);
    }
}
